<script setup lang="ts">
import type{components}from'~/api/schema';import{unwrap}from'~/api/client';import{displayError}from'~/utils/errors';import{formatDate,formatRupiah,statusLabel}from'~/utils/format';type Order=components['schemas']['VendorOrderPrivate'];
definePageMeta({middleware:'auth'});const api=useMarketplaceApi();const portal=usePortal();const items=ref<Order[]>([]);const pending=ref(true);const error=ref<unknown>();const filter=ref('ALL');const visible=computed(()=>filter.value==='ALL'?items.value:items.value.filter(x=>x.fulfillment_status===filter.value));
async function load(){pending.value=true;error.value=undefined;try{if(!portal.activeStore.value)await portal.loadStores();if(!portal.storeId.value)return;items.value=unwrap(await api.GET('/vendor/stores/{storeId}/orders',{params:{path:{storeId:portal.storeId.value},query:{limit:100}},cache:'no-store'})).items;}catch(cause){error.value=cause;}finally{pending.value=false;}}watch(()=>portal.storeId.value,()=>{void load();});onMounted(()=>{void load();});useSeoMeta({title:'Pesanan vendor — Niaga'});
</script>
<template><main id="main-content" class="page-shell"><PortalNav area="vendor"/><div class="section-heading"><div><p class="eyebrow">Pemenuhan</p><h1>Pesanan toko</h1></div><div class="form-actions"><StoreSwitcher/><select v-model="filter"><option value="ALL">Semua</option><option value="UNFULFILLED">Belum diproses</option><option value="PROCESSING">Diproses</option><option value="SHIPPED">Dikirim</option><option value="DELIVERED">Tiba</option><option value="COMPLETED">Selesai</option><option value="REVIEW">Review</option></select></div></div><ApiState :pending="pending" :error="error?displayError(error):null" :empty="!pending&&!visible.length" empty-title="Belum ada pesanan" @retry="load"><div class="order-list"><NuxtLink v-for="order in visible" :key="order.id" class="surface order-card" :to="`/vendor/pesanan/${order.id}`"><header><div><strong>{{ order.order_number }}</strong><small>{{ formatDate(order.created_at) }} · {{ order.items.length }} item</small></div><span class="badge">{{ statusLabel(order.fulfillment_status) }}</span></header><footer><span>Hak bersih {{ formatRupiah(order.payable_amount) }}</span><strong>{{ formatRupiah(order.buyer_total) }}</strong></footer></NuxtLink></div></ApiState></main></template>
